 for(int kind=0;kind<3;kind++){memset(f,9,61441);out[61440]=7;for(int i=0;i<61440;i++){gak_element(i,1536,kind,F(a,61440),F(time,1536),F(residual,kind==1?61440:0),F(out,61440),U(f,61440));float expected=(float)(a[i]+time[i%1536]);if(kind==1)expected=(float)(expected+residual[i]);if(kind==2&&expected<0)expected=0;equal(out[i],expected,0);assert(f[i]==0);}assert(out[61440]==7&&f[61440]==9);}
 memset(f,9,5281);out[5280]=7;for(int i=0;i<5280;i++){gak_euler(i,F(a,5280),F(p,5280),F(out,5280),U(f,5280));equal(out[i],(float)(a[i]+(float)(.25f*p[i])),0);assert(f[i]==0);}assert(out[5280]==7&&f[5280]==9);
